WITH session_stats AS (SELECT session_id, COUNT(duration_sec) AS duration_sec_count, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.started_at, sessions.customer_id, session_stats.duration_sec_count, session_stats.event_type_list FROM sessions LEFT OUTER JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.duration_sec_count > 10
